Fixpoint dsjb (V : list ivl) (a n : Z) : bool :=
  match V with [] => true | (lo, hi) :: V' => ((a + n <=? lo) || (hi <=? a)) && dsjb V' a n end.
Lemma dsjb_sound : forall V a n, dsjb V a n = true -> disjoint_from V a n.
Proof.
